import assert from 'node:assert/strict';
import {sizeTrade,RISK_POLICY} from '../../market-intelligence/risk-policy.mjs';
const plan={symbol:'BTCUSDT',side:'long',entry:100,stop:95,target:115};
const run=(other={})=>sizeTrade({equity:10000,positions:[],orders:[],plan,...other});
const base=run();
assert.equal(base.status,'calculated');
assert.equal(base.ordersEnabled,false);
assert.equal(base.perTradeBudget,100);
assert.equal(base.limits.perTradePct,1);
assert.equal(base.limits.portfolioPct,3);
assert.ok(base.allowedLoss<=100);
assert.ok(base.maxQuantityUnrounded*base.riskPerUnit<=100.00001);
const existing=[{symbol:'ETHUSDT',side:'Buy',size:'20',avgPrice:'100',markPrice:'100',stopLoss:'90'}];
const used=run({positions:existing});
assert.equal(used.status,'calculated');
assert.ok(used.currentRisk>200&&used.currentRisk<300);
const profitable=run({positions:[{side:'Buy',size:'20',avgPrice:'100',markPrice:'110',stopLoss:'90'}]});
assert.ok(profitable.currentRisk>used.currentRisk,'Mark-to-stop exposure must increase after unrealised gains');
assert.ok(profitable.allowedLoss<used.allowedLoss);
assert.ok(used.allowedLoss<100&&used.allowedLoss>0,'3% portfolio cap must limit position');
const full=run({positions:[{symbol:'ETHUSDT',side:'Buy',size:'30',avgPrice:'100',markPrice:'100',stopLoss:'90'}]});
assert.equal(full.status,'blocked');
assert.equal(full.remainingRisk,0);
const noStop=run({positions:[{side:'Buy',size:'1',avgPrice:'100',markPrice:'100',stopLoss:''}]});
assert.equal(noStop.status,'blocked');
assert.equal(run({positions:null}).status,'blocked');
assert.equal(run({orders:null}).status,'blocked');
assert.equal(run({positions:[{side:'Buy',size:'1',avgPrice:'100',stopLoss:'90'}]}).status,'blocked', 'Mark price is required for equity-based risk');
assert.equal(run({equity:''}).status,'blocked');
assert.equal(run({equity:0}).status,'blocked');
assert.equal(run({orders:[{orderStatus:'New',qty:'5',leavesQty:'5'}]}).status,'blocked');
assert.equal(run({orders:[{orderStatus:'Unknown',qty:'5'}]}).status,'blocked');
assert.equal(run({plan:{symbol:'BTCUSDT',side:'short',entry:100,stop:95,target:90}}).status,'blocked');
assert.equal(run({plan:null}).status,'blocked');
const short=run({plan:{symbol:'BTCUSDT',side:'short',entry:100,stop:105,target:85}});
assert.equal(short.status,'calculated');
assert.ok(short.allowedLoss<=100);
console.log('PASS: 1% per-trade, 3% aggregate, stop-loss, active orders, invalid balances, short/long and no-order protection');
